    pairs = [(k, v) for k, v in colors.items() if k != bg]
    pairs.sort(key=lambda x: x[1], reverse=True)
    wall_color = pairs[0][0] if pairs else 0
    source_color = pairs[1][0] if len(pairs) > 1 else 0

