    K_sum = None
    K_diff = None
    for r, c in source_points:
        K_sum = r + c
        K_diff = r - c
        break

    # Check consistency
    cons_sum = all(r + c == K_sum for r, c in source_points)
    cons_diff = all(r - c == K_diff for r, c in source_points)

    # Determine axis and reflected line
    axis = w_max_c + 1 if is_horizontal else w_max_r + 1

    output = [row[:] for row in grid]

    if is_horizontal:
        # Horizontal wall, reflection across row axis
        # Slope swaps (+1 <-> -1)
        if cons_sum:
