            for r in range(axis, rows):
                if 0 <= K_prime - r < cols:
                    start_c = K_prime - r
                    break
            if start_c is not None:
                for d in range(1, 10):
                    nr, nc = axis + d, start_c - d
                    if nr < rows and nc >= 0 and nc < cols:
                        if output[nr][nc] == bg:
                            output[nr][nc] = 3
    else:
        # Vertical wall, reflection across column axis
        # Slope swaps
        if cons_sum:
            # Source r+c=K, reflected c-r=2*axis-K -> c=r+(2*axis-K)
            shift = 2 * axis - K_sum
            for r in range(rows):
                c = r + shift
                if 0 <= c < cols and output[r][c] == bg:
                    output[r][c] = 3
